-- Drain API/worker, apply and reconcile manifest v12, then run bounded
-- search-projection repair for every tenant before restarting. This rebuilds
-- derived vectors only; immutable source/listing evidence is not rewritten.
DO $encoding$
BEGIN
  IF current_setting('server_encoding') <> 'UTF8' THEN
    RAISE EXCEPTION 'Catalog search requires UTF8 database encoding';
  END IF;
END
$encoding$;

CREATE FUNCTION catalog_core_lexical_terms_v1(value text) RETURNS text[]
LANGUAGE sql IMMUTABLE PARALLEL SAFE SET search_path = pg_catalog
AS $function$
  -- Unicode Letter | Number ranges from the pinned Go toolchain. The shared
  -- regression checks this class; a toolchain Unicode update needs review.
  -- Query text is bounded to 500 bytes. Longer document terms cannot match and
  -- are omitted rather than exceeding PostgreSQL's 2047-byte lexeme bound.
  SELECT coalesce(array_agg(DISTINCT term COLLATE "C"),ARRAY[]::text[])
    -- PostgreSQL 18 uses Unicode 16; Go's Unicode 17 tables add these mappings.
    -- Supplement only those mappings, without full case/compatibility folding.
    FROM unnest(regexp_split_to_array(translate(lower(coalesce(value,'') COLLATE pg_catalog.pg_c_utf8),
      U&'\A7CE\A7D2\A7D4\+016EA0\+016EA1\+016EA2\+016EA3\+016EA4\+016EA5\+016EA6\+016EA7\+016EA8\+016EA9\+016EAA\+016EAB\+016EAC\+016EAD\+016EAE\+016EAF\+016EB0\+016EB1\+016EB2\+016EB3\+016EB4\+016EB5\+016EB6\+016EB7\+016EB8', U&'\A7CF\A7D3\A7D5\+016EBB\+016EBC\+016EBD\+016EBE\+016EBF\+016EC0\+016EC1\+016EC2\+016EC3\+016EC4\+016EC5\+016EC6\+016EC7\+016EC8\+016EC9\+016ECA\+016ECB\+016ECC\+016ECD\+016ECE\+016ECF\+016ED0\+016ED1\+016ED2\+016ED3'),
      U&'[^\0030-\0039\0041-\005A\0061-\007A\00AA\00B2-\00B3\00B5\00B9-\00BA\00BC-\00BE\00C0-\00D6\00D8-\00F6\00F8-\02C1\02C6-\02D1\02E0-\02E4\02EC\02EE\0370-\0374\0376-\0377\037A-\037D\037F\0386\0388-\038A\038C\038E-\03A1\03A3-\03F5\03F7-\0481\048A-\052F\0531-\0556\0559\0560-\0588\05D0-\05EA\05EF-\05F2\0620-\064A\0660-\0669\066E-\066F\0671-\06D3\06D5\06E5-\06E6\06EE-\06FC\06FF\0710\0712-\072F\074D-\07A5\07B1\07C0-\07EA\07F4-\07F5\07FA\0800-\0815\081A\0824\0828\0840-\0858\0860-\086A\0870-\0887\0889-\088F\08A0-\08C9\0904-\0939\093D\0950\0958-\0961\0966-\096F\0971-\0980\0985-\098C\098F-\0990\0993-\09A8\09AA-\09B0\09B2\09B6-\09B9\09BD\09CE\09DC-\09DD\09DF-\09E1\09E6-\09F1\09F4-\09F9\09FC\0A05-\0A0A\0A0F-\0A10\0A13-\0A28\0A2A-\0A30\0A32-\0A33\0A35-\0A36\0A38-\0A39\0A59-\0A5C\0A5E\0A66-\0A6F\0A72-\0A74\0A85-\0A8D\0A8F-\0A91\0A93-\0AA8\0AAA-\0AB0\0AB2-\0AB3\0AB5-\0AB9\0ABD\0AD0\0AE0-\0AE1\0AE6-\0AEF\0AF9\0B05-\0B0C\0B0F-\0B10\0B13-\0B28\0B2A-\0B30\0B32-\0B33\0B35-\0B39\0B3D\0B5C-\0B5D\0B5F-\0B61\0B66-\0B6F\0B71-\0B77\0B83\0B85-\0B8A\0B8E-\0B90\0B92-\0B95\0B99-\0B9A\0B9C\0B9E-\0B9F\0BA3-\0BA4\0BA8-\0BAA\0BAE-\0BB9\0BD0\0BE6-\0BF2\0C05-\0C0C\0C0E-\0C10\0C12-\0C28\0C2A-\0C39\0C3D\0C58-\0C5A\0C5C-\0C5D\0C60-\0C61\0C66-\0C6F\0C78-\0C7E\0C80\0C85-\0C8C\0C8E-\0C90\0C92-\0CA8\0CAA-\0CB3\0CB5-\0CB9\0CBD\0CDC-\0CDE\0CE0-\0CE1\0CE6-\0CEF\0CF1-\0CF2\0D04-\0D0C\0D0E-\0D10\0D12-\0D3A\0D3D\0D4E\0D54-\0D56\0D58-\0D61\0D66-\0D78\0D7A-\0D7F\0D85-\0D96\0D9A-\0DB1\0DB3-\0DBB\0DBD\0DC0-\0DC6\0DE6-\0DEF\0E01-\0E30\0E32-\0E33\0E40-\0E46\0E50-\0E59\0E81-\0E82\0E84\0E86-\0E8A\0E8C-\0EA3\0EA5\0EA7-\0EB0\0EB2-\0EB3\0EBD\0EC0-\0EC4\0EC6\0ED0-\0ED9\0EDC-\0EDF\0F00\0F20-\0F33\0F40-\0F47\0F49-\0F6C\0F88-\0F8C\1000-\102A\103F-\1049\1050-\1055\105A-\105D\1061\1065-\1066\106E-\1070\1075-\1081\108E\1090-\1099\10A0-\10C5\10C7\10CD\10D0-\10FA\10FC-\1248\124A-\124D\1250-\1256\1258\125A-\125D\1260-\1288\128A-\128D\1290-\12B0\12B2-\12B5\12B8-\12BE\12C0\12C2-\12C5\12C8-\12D6\12D8-\1310\1312-\1315\1318-\135A\1369