CREATE FUNCTION catalog_core_sort_name_v1(value text) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE SET search_path = pg_catalog
AS $function$
  SELECT translate(lower(btrim(regexp_replace(coalesce(value,'') COLLATE pg_catalog.pg_c_utf8, '\s+', ' ', 'g'))),
    U&'\A7CE\A7D2\A7D4\+016EA0\+016EA1\+016EA2\+016EA3\+016EA4\+016EA5\+016EA6\+016EA7\+016EA8\+016EA9\+016EAA\+016EAB\+016EAC\+016EAD\+016EAE\+016EAF\+016EB0\+016EB1\+016EB2\+016EB3\+016EB4\+016EB5\+016EB6\+016EB7\+016EB8', U&'\A7CF\A7D3\A7D5\+016EBB\+016EBC\+016EBD\+016EBE\+016EBF\+016EC0\+016EC1\+016EC2\+016EC3\+016EC4\+016EC5\+016EC6\+016EC7\+016EC8\+016EC9\+016ECA\+016ECB\+016ECC\+016ECD\+016ECE\+016ECF\+016ED0\+016ED1\+016ED2\+016ED3')
$function$;
REVOKE ALL ON FUNCTION catalog_core_sort_name_v1(text) FROM PUBLIC;

-- Qualify helper calls at definition time: a caller-controlled search_path
-- must not redirect normalization, and runtime calls need no dynamic SQL.
DO $definitions$
DECLARE schema_name text := '"' || replace(current_schema(), '"', '""') || '"';
BEGIN
  EXECUTE format($ddl$
    CREATE OR REPLACE FUNCTION catalog_core_lexical_vector_v1(value text) RETURNS tsvector
    LANGUAGE sql IMMUTABLE PARALLEL SAFE SET search_path = pg_catalog
    AS $function$ SELECT array_to_tsvector(%s.catalog_core_lexical_terms_v1(value)) $function$
  $ddl$, schema_name);
  EXECUTE format($ddl$
    CREATE OR REPLACE FUNCTION catalog_core_lexical_query_v1(value text) RETURNS tsquery
    LANGUAGE sql IMMUTABLE PARALLEL SAFE SET search_path = pg_catalog
    AS $function$
      SELECT coalesce(string_agg(quote_literal(term),' & '),'')::tsquery
      FROM unnest(%s.catalog_core_lexical_terms_v1(value)) AS tokens(term)
    $function$
  $ddl$, schema_name);
  EXECUTE format($ddl$
    CREATE OR REPLACE FUNCTION project_observation_catalog_search() RETURNS trigger
    LANGUAGE plpgsql SET search_path = pg_catalog
    AS $function$
    DECLARE document jsonb;
    BEGIN
      NEW.search_vector_version := 2;
      IF NEW.normalized_entry_digest IS NULL OR NEW.normalized_entry_bytes IS NULL THEN
        NEW.search_display_name := NULL;
        NEW.search_description := NULL;
        NEW.search_tags := NULL;
        NEW.search_representative_queries := NULL;
        NEW.search_publisher := NULL;
        NEW.search_vector := NULL;
        RETURN NEW;
      END IF;
      document := convert_from(NEW.normalized_entry_bytes,'UTF8')::jsonb;
      NEW.search_display_name := coalesce(document->>'displayName','');
      NEW.search_description := coalesce(document->>'description','');
      SELECT coalesce(array_agg(DISTINCT lower(btrim(value) COLLATE pg_catalog.pg_c_utf8) COLLATE "C"),ARRAY[]::text[])
        INTO NEW.search_tags
        FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(document->'tags')='array' THEN document->'tags' ELSE '[]'::jsonb END)
        WHERE btrim(value)<>'';
      SELECT coalesce(array_agg(value ORDER BY ordinality),ARRAY[]::text[])
        INTO NEW.search_representative_queries
        FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(document->'representativeQueries')='array' THEN document->'representativeQueries' ELSE '[]'::jsonb END) WITH ORDINALITY AS queries(value,ordinality);
      NEW.search_publisher := split_part(NEW.identifier,':',3);
      NEW.search_vector := %s.catalog_core_lexical_vector_v1(
        concat_ws(' ',NEW.identifier,NEW.search_display_name,NEW.search_description,
          array_to_string(NEW.search_tags,' '),array_to_string(NEW.search_representative_queries,' ')));
      RETURN NEW;
    END
    $function$
  $ddl$, schema_name);
END
$definitions$;

-- A constant default marks retained rows without an unbounded migration
-- backfill. The projection trigger stamps 2 on every new/repaired observation.
ALTER TABLE observations ADD COLUMN search_vector_version integer NOT NULL DEFAULT 1
  CHECK (search_vector_version IN (1,2));
DROP INDEX observations_catalog_search_projection_missing;
CREATE INDEX observations_catalog_search_projection_missing
  ON observations (tenant_id,id)
  WHERE normalized_entry_digest IS NOT NULL
    AND (search_display_name IS NULL OR search_description IS NULL OR search_tags IS NULL
      OR search_representative_queries IS NULL OR search_publisher IS NULL OR search_vector IS NULL
      OR search_vector_version<>2);
COMMENT ON COLUMN observations.search_vector_version IS 'Derived lexical projection format: 1 requires bounded owner repair; 2 uses shared Unicode Letter/Number tokens.';
COMMENT ON INDEX observations_catalog_search_projection_missing IS 'Sparse inventory for incomplete or outdated derived Catalog search projections.';
